package com.queueguard.qms.service;
import com.queueguard.common.exception.*; import com.queueguard.qms.domain.*; import com.queueguard.qms.dto.QmsDtos.*; import com.queueguard.qms.repo.*; import org.junit.jupiter.api.*; import java.lang.reflect.Field; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class TenantServiceTest {
 OrganizationRepository orgs; MembershipRepository members; TenantService service;
 @BeforeEach void init(){orgs=mock(OrganizationRepository.class);members=mock(MembershipRepository.class);service=new TenantService(orgs,members);}
 @Test void onboardingCreatesActiveAdminMembership()throws Exception{when(orgs.save(any())).thenAnswer(i->{Organization o=i.getArgument(0);set(o,"id",1L);return o;});OrganizationView out=service.onboard(10L,new CreateOrganizationRequest("Alpha College","COLLEGE"));assertEquals("Alpha College",out.name());verify(members).save(argThat(m->m.getAuthUserId().equals(10L)&&m.getRoles().contains(OrganizationRole.ORG_ADMIN)));}
 @Test void duplicateOrganizationIsRejected(){when(orgs.existsByNameIgnoreCase("Alpha")).thenReturn(true);assertThrows(BusinessException.class,()->service.onboard(1L,new CreateOrganizationRequest("Alpha","COLLEGE")));}
 @Test void userCanHaveMembershipsInMultipleOrganizations()throws Exception{Membership a=membership(1,10,OrganizationRole.MEMBER);Membership b=membership(2,10,OrganizationRole.INTERVIEWER);when(members.findByAuthUserIdOrderByCreatedAtDesc(10L)).thenReturn(List.of(a,b));assertEquals(2,service.mine(10L).size());}
 @Test void nonAdminCannotModifyMembership()throws Exception{Membership caller=membership(1,10,OrganizationRole.MEMBER);when(members.findByOrganizationIdAndAuthUserId(1L,10L)).thenReturn(Optional.of(caller));assertThrows(ForbiddenException.class,()->service.add(10L,1L,new AddMembershipRequest(20L,Set.of(OrganizationRole.MEMBER))));}
 @Test void crossTenantMembershipIdIsNotExposed()throws Exception{Membership admin=membership(1,10,OrganizationRole.ORG_ADMIN);Membership other=membership(2,20,OrganizationRole.MEMBER);when(members.findByOrganizationIdAndAuthUserId(1L,10L)).thenReturn(Optional.of(admin));when(members.findById(99L)).thenReturn(Optional.of(other));assertThrows(NotFoundException.class,()->service.roles(10L,1L,99L,new UpdateRolesRequest(Set.of(OrganizationRole.INTERVIEWER))));}
 @Test void suspendedMembershipCannotReadOrganization()throws Exception{Membership m=membership(1,10,OrganizationRole.ORG_ADMIN);m.setStatus(MembershipStatus.SUSPENDED);when(members.findByOrganizationIdAndAuthUserId(1L,10L)).thenReturn(Optional.of(m));assertThrows(ForbiddenException.class,()->service.organization(10L,1L));}
 static Membership membership(long org,long user,OrganizationRole role)throws Exception{Organization o=new Organization();set(o,"id",org);o.setName("Org"+org);o.setOrganizationType("COLLEGE");Membership m=new Membership();m.setOrganization(o);m.setAuthUserId(user);m.setRoles(Set.of(role));return m;}
 static void set(Object o,String f,Object v)throws Exception{Field x=o.getClass().getDeclaredField(f);x.setAccessible(true);x.set(o,v);}
}
